-- Category canonicalization for the shared technique library (add_teq).
--
-- AI-written categories for requested/discovered techniques had split each
-- art's real categories into near-duplicates ("escape" / "Escape" /
-- "탈출 (Escape)", "Escapes / Reversals", "conditioning/warm-up", ...). The
-- canonical category set is each art's OWN official categories (the
-- encyclopedia's section headings, data/processed). Every row below was
-- reclassified one technique at a time (data/curated/category-canonical.json
-- "records" — e.g. the mixed "Escapes / Reversals" row went to 리버설 by what
-- that technique actually is, not by its old label).
--
-- Safety / no data loss:
--   - only the category changes; the previous value is kept in
--     data.technique.categoryOriginal,
--   - each update matches the exact old category, so re-running is a no-op
--     and a row someone already changed is left alone,
--   - no row is deleted; rows that duplicated an official technique are
--     resolved to it in the app (technique-canonical.json addTeqDuplicates),
--     not removed here.
-- Rollback (per row):
--   update public.add_teq
--   set category = data->'technique'->>'categoryOriginal',
--       data = jsonb_set(data #- '{technique,categoryOriginal}', '{technique,category}', data->'technique'->'categoryOriginal')
--   where data->'technique' ? 'categoryOriginal';
-- RLS is unchanged (migrations run as the table owner; clients still have no UPDATE policy).

update public.add_teq set category = '탈출 기술 모음', updated_at = now(), data = jsonb_set(jsonb_set(data, '{technique,categoryOriginal}', to_jsonb(category)), '{technique,category}', to_jsonb('탈출 기술 모음'::text)) where id = 'bjj__그립-브레이킹-턴-아웃' and category = 'escape';
update public.add_teq set category = '사이드 컨트롤 (Side Control)', updated_at = now(), data = jsonb_set(jsonb_set(data, '{technique,categoryOriginal}', to_jsonb(category)), '{technique,category}', to_jsonb('사이드 컨트롤 (Side Control)'::text)) where id = 'bjj__buggy-choke' and category = 'Submission';
