update public.add_teq set category = '기본 자세와 움직임', updated_at = now(), data = jsonb_set(jsonb_set(data, '{technique,categoryOriginal}', to_jsonb(category)), '{technique,category}', to_jsonb('기본 자세와 움직임'::text)) where id = 'wrestling__핸드-스탠드' and category = 'conditioning/warm-up';
